import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"48、【井】 巽下坎上","description":"周易口訣義 - 48、【井】 巽下坎上","frontmatter":{"title":"48、【井】 巽下坎上","description":"周易口訣義 - 48、【井】 巽下坎上"},"headers":[],"relativePath":"classics/koujueyi/050.md","filePath":"classics/koujueyi/050.md"}'),r={name:"classics/koujueyi/050.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_48、【井】-巽下坎上" tabindex="-1">48、【井】 巽下坎上 <a class="header-anchor" href="#_48、【井】-巽下坎上" aria-label="Permalink to “48、【井】 巽下坎上”">​</a></h1><p>彖曰：巽乎水而上水，井。井養而不窮也。「改邑不改井」，乃以剛中也。「汔至亦未繘井」，未有功也。「羸其瓶」，是以兇也。</p><p>象曰：木上有水，井，君子以勞民勸相。</p><p>初六，井泥不食，舊井無禽。</p><p>象曰：「井泥不食」，下也；「舊井無禽」，時舍也。</p><p>九二，井谷射鮒，甕敝漏。</p><p>象曰：「井谷射鮒」，無與也。</p><p>九三，井渫不食，為我心惻，可用汲，王明，並受其福。</p><p>象曰：「井渫不食」，行惻也；求「王明」，受福也。</p><p>六四，井甃，無咎。</p><p>象曰：「井甃無咎」，修井也。</p><p>九五，井洌寒泉，食。</p><p>象曰：「寒泉之食」，中正也。</p><p>上六，井收勿幕，有孚元吉。</p><p>象曰：「元吉」在上，大成也。</p><p>解讀</p><p>「井改邑不改井」者，古人穿地汲水以供人用，故謂之井，井以潔淨為義也。邑，民產也，其屋遷移，井體不改，亦猶人之常德，改過不吝，德行有恆，故曰「改邑不改井」也。「往來井井」者，往者來者皆汲引之，而不以貴賤汲引改其清潔之性也。無喪無得者，此舉井體有恆，不隨物之遷變，故終日泉注未嘗言溢，終日汲引未嘗言竭也。「汔至亦未繘井，羸其瓶，兇」者，繘，綆繩也；汔，將至之義；羸，舒展也。言汲水將至井口，其綆猶未盡出，而鉤舒繩斷，傾覆其瓶，即是勞而無功。喻人行其恩德，須善始令終，若有始無終，不能永保其故，就人事言兇也。書雲「為山九仞，功虧一簣」，是也。象曰「木上有水」，即是汲水而上井之象也。「君子以勞民勸相」者，勞，賚；相，助也。井之為義，養而不窮，以勞賚之恩，勸恤勤惠，令助百姓，使有成功，故周弘正雲「勸助民人，使功日濟」，是也。</p><p>「初六，井泥不食，舊井無禽」者，初六最處井底，即是井下淤泥沉滓而不可食。井既舊穢，不曾淘渫，即禽鳥賤類，而尚不向，即人與禽俱在棄捨，故曰「舊井無禽」，喻人不潔己修行，為人所棄是也。</p><p>「九二，井谷射鮒，甕敝漏」者，鮒，井底小魚也。夫井之為道，以下給上為義，今九二與初六相近而附於初，即是附給下之義。如以溪谷之水，從上注下，射轍鮒魚，故曰「井谷射鮒」也。井不上汲，反以下注，失井之道，又似甕之破漏，出水而注下，故曰「甕敝漏」也。子夏傳曰：「鮒是蝦蟆也。」</p><p>「九三，井渫不食，為我心惻，可用汲，王明，並受其福」者，為，猶使也；渫，治也。言井既淘渫修治，其水清潔，可以食之，猶人德行已成，可以任用，今既不食，即使我中心惻愴，故曰「井渫不食，為我心惻」。若王者明鑑，用我以為輔弼，既喜其行，又欽其用，故曰「王明，並受其福」也。得人助己而化洽，民之有幸，故獲其福矣。</p><p>「六四，井甃，無咎」者，甃，猶修治也，壞處以磚甃壘也。六四得位無應，得位即可以自處，無應即不可以行，其猶人之為道，無施行之功，即可以修德自處，故「無咎」也。</p><p>「九五，井洌寒泉食」者，洌，清潔也；「寒」者，表清潔之義也。餘爻不當貴位，皆修德待用。九五既居尊位，能擇人而用之，以剛居中，下無私應，剛中即能斷制非妄，下無私應即無偏曲之心，猶剛正之主不任貪濁之臣，必須行潔賢明而後始用，故曰「寒泉食」也。</p><p>「上六：井收，勿幕，有孚，無吉」者，凡五穀收成倍於常年者曰「收」也。上六處井之極，井道大成，如五穀之有收成，故曰「井收」也。「幕」是覆蓋也。井既大成，不須覆蓋而不私其利，使天下悉皆汲引，即是信被天下而致大成，故獲大吉，故曰「勿幕有孚元吉」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
